// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/auth/register", wrapper.Register)
	router.POST(options.BaseURL+"/auth/register/verify", wrapper.VerifyRegistration)
	router.POST(options.BaseURL+"/auth/register/resend", wrapper.ResendRegistrationVerification)
	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/refresh", wrapper.Refresh)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/tracks", wrapper.GetAllTracks)
	router.GET(options.BaseURL+"/tracks/metadata/search", wrapper.SearchTrackMetadata)
	router.POST(options.BaseURL+"/tracks/upload", wrapper.UploadTrack)
	router.GET(options.BaseURL+"/tracks/:trackId/content", wrapper.GetTrackContent)
	router.DELETE(options.BaseURL+"/tracks/:trackId", wrapper.DeleteTrack)
	router.GET(options.BaseURL+"/tracks/:trackId", wrapper.GetTrackByID)
	router.PUT(options.BaseURL+"/tracks/:trackId", wrapper.UpdateTrack)
	router.GET(options.BaseURL+"/playlists", wrapper.GetAllPlaylists)
	router.POST(options.BaseURL+"/playlists", wrapper.CreatePlaylist)
	router.DELETE(options.BaseURL+"/playlists/:playlistId", wrapper.DeletePlaylist)
	router.GET(options.BaseURL+"/playlists/:playlistId", wrapper.GetPlaylistByID)
	router.PUT(options.BaseURL+"/playlists/:playlistId", wrapper.UpdatePlaylist)
	router.DELETE(options.BaseURL+"/playlists/:playlistId/tracks/:trackId", wrapper.RemoveTrackFromPlaylist)
	router.POST(options.BaseURL+"/playlists/:playlistId/tracks/:trackId", wrapper.AddTrackToPlaylist)
}

