// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Login user
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Logout user
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Refresh Refresh access token
	// (POST /auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// Register Start user registration
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// ResendRegistrationVerification Resend registration verification code
	// (POST /auth/register/resend)
	ResendRegistrationVerification(ctx context.Context, request ResendRegistrationVerificationRequestObject) (ResendRegistrationVerificationResponseObject, error)
	// VerifyRegistration Verify user email during registration
	// (POST /auth/register/verify)
	VerifyRegistration(ctx context.Context, request VerifyRegistrationRequestObject) (VerifyRegistrationResponseObject, error)
	// GetAllPlaylists Get all playlists available for the user
	// (GET /playlists)
	GetAllPlaylists(ctx context.Context, request GetAllPlaylistsRequestObject) (GetAllPlaylistsResponseObject, error)
	// CreatePlaylist Create playlist
	// (POST /playlists)
	CreatePlaylist(ctx context.Context, request CreatePlaylistRequestObject) (CreatePlaylistResponseObject, error)
	// DeletePlaylist Delete playlist
	// (DELETE /playlists/{playlistId})
	DeletePlaylist(ctx context.Context, request DeletePlaylistRequestObject) (DeletePlaylistResponseObject, error)
	// GetPlaylistByID Get playlist by ID
	// (GET /playlists/{playlistId})
	GetPlaylistByID(ctx context.Context, request GetPlaylistByIDRequestObject) (GetPlaylistByIDResponseObject, error)
	// UpdatePlaylist Update playlist
	// (PUT /playlists/{playlistId})
	UpdatePlaylist(ctx context.Context, request UpdatePlaylistRequestObject) (UpdatePlaylistResponseObject, error)
	// RemoveTrackFromPlaylist Remove track from playlist
	// (DELETE /playlists/{playlistId}/tracks/{trackId})
	RemoveTrackFromPlaylist(ctx context.Context, request RemoveTrackFromPlaylistRequestObject) (RemoveTrackFromPlaylistResponseObject, error)
	// AddTrackToPlaylist Add track to playlist
	// (POST /playlists/{playlistId}/tracks/{trackId})
	AddTrackToPlaylist(ctx context.Context, request AddTrackToPlaylistRequestObject) (AddTrackToPlaylistResponseObject, error)
	// GetAllTracks Get all tracks
	// (GET /tracks)
	GetAllTracks(ctx context.Context, request GetAllTracksRequestObject) (GetAllTracksResponseObject, error)
	// SearchTrackMetadata Search MusicBrainz recordings
	// (GET /tracks/metadata/search)
	SearchTrackMetadata(ctx context.Context, request SearchTrackMetadataRequestObject) (SearchTrackMetadataResponseObject, error)
	// UploadTrack Upload a track
	// (POST /tracks/upload)
	UploadTrack(ctx context.Context, request UploadTrackRequestObject) (UploadTrackResponseObject, error)
	// DeleteTrack Delete track
	// (DELETE /tracks/{trackId})
	DeleteTrack(ctx context.Context, request DeleteTrackRequestObject) (DeleteTrackResponseObject, error)
	// GetTrackByID Get track by ID
	// (GET /tracks/{trackId})
	GetTrackByID(ctx context.Context, request GetTrackByIDRequestObject) (GetTrackByIDResponseObject, error)
	// UpdateTrack Update track
	// (PUT /tracks/{trackId})
	UpdateTrack(ctx context.Context, request UpdateTrackRequestObject) (UpdateTrackResponseObject, error)
	// GetTrackContent Get a temporary track content URL
	// (GET /tracks/{trackId}/content)
	GetTrackContent(ctx context.Context, request GetTrackContentRequestObject) (GetTrackContentResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

